"use client";

import { useId, useState, type ComponentProps } from "react";

import { IconCheck, IconShieldCheck } from "@rhs-ui/icons";
import { formatMoney } from "@rhs-ui/commerce/money";
import {
  PERIODS,
  PERIOD_DAYS,
  dateOfDay,
  dayOfDate,
  dayOfInput,
  quoteRental,
  utcDateOf,
  windowFor,
  type RentalLine,
  type RentalPeriod,
  type RentalPrices,
} from "@rhs-ui/commerce/rental-rates/pricing";
import { RangeCalendar } from "@rhs-ui/commerce/rental-rates/range-calendar";
import { cn } from "@/lib/utils";

export type { RentalPeriod, RentalPrices } from "@rhs-ui/commerce/rental-rates/pricing";

/** The days of a rental, the way the house date pickers hand them out: Dates at midnight in the reader's time zone. */
export interface RentalRange {
  /** The pick-up day, or null. */
  from: Date | null;
  /** The return day, or null while it is being chosen. */
  to: Date | null;
}

/** The same range as it can be passed in: a Date, or a plain "2026-11-20" that is the same day everywhere. */
export interface RentalRangeInput {
  /** The pick-up day: a Date, a plain "2026-11-20" or null while nothing is picked. */
  from: Date | string | null;
  /** The return day: a Date, a plain "2026-11-20" or null while it is being chosen. */
  to: Date | string | null;
}

export interface RentalRatesLabels {
  /** The heading. */
  title?: string;
  /** The caption of the rate tiles. */
  rates?: string;
  /** The names of the four rates. */
  periods?: Partial<Record<RentalPeriod, string>>;
  /** What each rate covers, under its price. */
  covers?: Partial<Record<RentalPeriod, string>>;
  /** The price of one day of a rate. `{amount}`: "€25.71 / day". */
  perDay?: string;
  /** Said to a screen reader on the rates that are in the total. */
  inTotal?: string;
  /** The caption of the chosen dates. */
  dates?: string;
  /** Before any day is picked. */
  pickDates?: string;
  /** After the pick-up day, when any later day can be the return day. */
  pickReturn?: string;
  /** After the pick-up day, when a booking ends the choice. `{date}` is the last day that can be picked. */
  pickReturnUntil?: string;
  /** Two days. `{from}` and `{to}`. */
  range?: string;
  /** A number of days, for one day. `{count}`. */
  daysOne?: string;
  /** A number of days, for any other number. `{count}`. */
  daysOther?: string;
  /** A line of the breakdown. `{period}`: "Weekend rate". */
  rateName?: string;
  /** A rate in a sentence. `{days}` and `{period}`: "3 days at the weekend rate". */
  atRate?: string;
  /** What the cheapest combination saves. `{what}` and `{amount}`. */
  saves?: string;
  /** Said when no rate covers the days. */
  noRate?: string;
  /** The total row. */
  total?: string;
  /** Said in place of the total until both days are picked. */
  noTotal?: string;
  /** The deposit row. */
  deposit?: string;
  /** Under the deposit: that it is refundable, and not part of the total. */
  depositHint?: string;
  /** Said under the chosen dates when picking a rate moved them to a free stretch. `{from}` and `{to}` are the new days, `{period}` the rate: "Your dates moved to Fri 13 Nov – Sun 15 Nov: the next free stretch for a weekend." */
  moved?: string;
  /** The button to the previous month. */
  previousMonth?: string;
  /** The button to the next month. */
  nextMonth?: string;
  /** Added to the name of the pick-up day in the calendar. */
  pickUp?: string;
  /** Added to the name of the return day in the calendar. */
  returnDay?: string;
  /** Added to the name of a booked day in the calendar. */
  bookedDay?: string;
  /** Added to the name of a day that cannot be picked for another reason. */
  unavailableDay?: string;
  /** The booked days of the month. `{dates}`. */
  bookedList?: string;
  /** Said when nothing is booked in the month on show. `{month}`. */
  nothingBooked?: string;
}

const WORDS = {
  title: "Rental rates",
  rates: "Rates",
  periods: { day: "Day", weekend: "Weekend", week: "Week", month: "Month" },
  covers: { day: "1 day", weekend: "Friday to Sunday", week: "7 days", month: "30 days" },
  perDay: "{amount} / day",
  inTotal: "In your total",
  dates: "Your dates",
  pickDates: "Pick a pick-up day and a return day.",
  pickReturn: "Now pick the return day. Pick the same day to rent for one day.",
  pickReturnUntil: "Now pick the return day. The last day you can pick is {date}, because the day after it is booked.",
  range: "{from} to {to}",
  daysOne: "{count} day",
  daysOther: "{count} days",
  rateName: "{period} rate",
  atRate: "{days} at the {period} rate",
  saves: "{what} saves {amount}.",
  noRate: "None of the rates covers these days.",
  total: "Rental total",
  noTotal: "Pick your dates to see the total.",
  deposit: "Refundable deposit",
  depositHint: "Held when you pick it up and released in full when it comes back undamaged. It is not part of the total.",
  moved: "Your dates moved to {from} – {to}: the next free stretch for a {period}.",
  previousMonth: "Previous month",
  nextMonth: "Next month",
  pickUp: "pick-up day",
  returnDay: "return day",
  bookedDay: "booked",
  unavailableDay: "not available",
  bookedList: "Booked: {dates}.",
  nothingBooked: "Nothing is booked in {month}.",
} satisfies Required<RentalRatesLabels>;

export interface RentalRatesProps extends Omit<ComponentProps<"div">, "children" | "title" | "onChange"> {
  /** The price of one whole period in minor units: `{ day: 3500, weekend: 9000, week: 18000, month: 52000 }`. Leave out the periods you do not offer. */
  rates: RentalPrices;
  /** The chosen days. Pass it, with `onRangeChange`, to control them; without it the component keeps them itself. Days that come from a server are safest as plain "2026-11-20" strings. */
  range?: RentalRangeInput;
  /** The days to start with when the component keeps them itself. */
  defaultRange?: RentalRangeInput;
  /** Called with the new days whenever a day is picked or a rate is chosen. */
  onRangeChange?: (range: RentalRange) => void;
  /** The deposit in minor units. It is shown apart from the total and described as refundable. */
  deposit?: number;
  /** ISO 4217 code for every amount. */
  currency?: string;
  /** Locale for the amounts, the dates and the month names. Always passed, so server and browser agree. */
  locale?: string;
  /** The days that are booked, as Dates or plain "2026-11-20" strings. They are struck through, cannot be picked and are named under the calendar. */
  unavailable?: readonly (Date | string)[];
  /** The first day that can be rented, usually today in the shop's time zone. Earlier days are dimmed and refused. The calendar opens on its month, so pass it from the server and both sides agree. */
  min?: Date | string;
  /** What is rented, under the heading: "Hilti TE 70 rotary hammer". */
  description?: string;
  /** 1 starts the calendar's weeks on a Monday (the default), 0 on a Sunday. */
  weekStartsOn?: 0 | 1;
  /** The words, for another language. */
  labels?: RentalRatesLabels;
}

const fill = (template: string, values: Record<string, string | number>): string => template.replace(/\{(\w+)\}/g, (_, key: string) => String(values[key] ?? ""));

/**
 * The prices of a rental, by the day, the weekend, the week and the month, and what the dates a customer picked
 * come to. It finds the cheapest combination of the rates for exactly those days ("3 days at the weekend rate
 * saves €15.00"), shows every rate with what a day costs on it, and keeps the deposit apart from the total and
 * says it is refundable. Booked days are struck through in the calendar, cannot be picked, and are named in
 * words under it; choosing a rate moves the dates to the next stretch where it is free. The total is a polite
 * status, so it is read out whenever the dates change.
 */
export function RentalRates({
  rates,
  range,
  defaultRange,
  onRangeChange,
  deposit,
  currency = "EUR",
  locale = "en-US",
  unavailable = [],
  min,
  description,
  weekStartsOn = 1,
  labels,
  className,
  ...props
}: RentalRatesProps) {
  const words = { ...WORDS, ...labels, periods: { ...WORDS.periods, ...labels?.periods }, covers: { ...WORDS.covers, ...labels?.covers } };
  const id = useId();
  const [own, setOwn] = useState<RentalRangeInput>(defaultRange ?? { from: null, to: null });
  const [notice, setNotice] = useState("");

  const source = range ?? own;
  const fromDay = source.from === null ? null : dayOfInput(source.from);
  const endDay = source.to === null ? null : dayOfInput(source.to);
  const toDay = fromDay !== null && endDay !== null && endDay >= fromDay ? endDay : null;
  const minDay = min === undefined ? null : dayOfInput(min);
  const booked = new Set(unavailable.map(dayOfInput).filter((day): day is number => day !== null));
  const blocked = (day: number) => booked.has(day) || (minDay !== null && day < minDay);
  // While the return day is being chosen, the next booking ends the choice.
  const nextBooked = fromDay !== null && toDay === null ? Math.min(Number.POSITIVE_INFINITY, ...[...booked].filter((day) => day > fromDay)) : Number.POSITIVE_INFINITY;
  const lastPickable = Number.isFinite(nextBooked) ? nextBooked - 1 : null;

  const money = (amount: number) => formatMoney({ amount, currency }, locale);
  const numbers = new Intl.NumberFormat(locale);
  const plural = new Intl.PluralRules(locale);
  const list = new Intl.ListFormat(locale, { style: "long", type: "conjunction" });
  const dayFormat = new Intl.DateTimeFormat(locale, { weekday: "short", day: "numeric", month: "short", timeZone: "UTC" });
  const dayText = (day: number) => dayFormat.format(utcDateOf(day));
  const daysText = (count: number) => fill(plural.select(count) === "one" ? words.daysOne : words.daysOther, { count: numbers.format(count) });
  const periodWord = (period: RentalPeriod) => words.periods[period].toLocaleLowerCase(locale);
  const atRate = (line: RentalLine) => fill(words.atRate, { days: daysText(line.days), period: periodWord(line.period) });

  const quote = fromDay !== null && toDay !== null ? quoteRental(rates, fromDay, toDay) : null;
  const applied = new Set(quote?.lines.map((line) => line.period));
  const selected = quote && quote.lines.length === 1 && quote.lines[0]?.blocks === 1 ? quote.lines[0].period : "";
  const offered = PERIODS.filter((period) => rates[period] !== undefined);
  const saving = quote && quote.saving > 0 ? fill(words.saves, { what: list.format(quote.lines.map(atRate)), amount: money(quote.saving) }) : null;

  const commit = (next: { from: number | null; to: number | null }) => {
    const out: RentalRange = { from: next.from === null ? null : dateOfDay(next.from), to: next.to === null ? null : dateOfDay(next.to) };
    if (range === undefined) setOwn(out);
    onRangeChange?.(out);
  };
  const pick = (day: number) => {
    setNotice("");
    if (fromDay === null || toDay !== null || day < fromDay) return commit({ from: day, to: null });
    if (lastPickable !== null && day > lastPickable) return;
    commit({ from: fromDay, to: day });
  };
  // A rate fills in the dates for one whole period, from the pick-up day if there is one.
  const choose = (period: RentalPeriod) => {
    const today = dayOfDate(new Date());
    const start = Math.max(fromDay ?? today, minDay ?? today);
    const found = windowFor(period, start, blocked);
    if (!found) return;
    commit(found);
    setNotice(fromDay !== null && found.from !== fromDay ? fill(words.moved, { from: dayText(found.from), to: dayText(found.to), period: periodWord(period) }) : "");
  };

  const caption = "text-xs font-medium text-muted-foreground";
  const groupName = `${id}-rate`;

  return (
    <div data-slot="rental-rates" role="group" aria-labelledby={`${id}-title`} className={cn("@container w-full min-w-0 rounded-xl border border-border bg-card text-card-foreground shadow-xs", className)} {...props}>
      <div className="px-5 pt-5">
        <h3 id={`${id}-title`} className="text-base leading-snug font-semibold tracking-[-0.01em]">
          {words.title}
        </h3>
        {description ? <p className="mt-1 text-sm text-muted-foreground">{description}</p> : null}
      </div>

      <fieldset className="grid gap-2.5 px-5 pt-4 pb-5">
        <legend className="sr-only">{words.rates}</legend>
        <div className="grid grid-cols-2 gap-2.5 @[34rem]:grid-cols-4">
          {offered.map((period) => {
            const price = rates[period] ?? 0;
            const on = applied.has(period);
            return (
              <label
                key={period}
                className={cn(
                  "relative flex min-w-0 cursor-pointer flex-col gap-0.5 rounded-xl border bg-background p-3.5 transition-[border-color,background-color] duration-150 hover:bg-muted/50 has-[:focus-visible]:ring-[3px] has-[:focus-visible]:ring-ring/40 motion-reduce:transition-none",
                  on ? "border-foreground bg-muted/50" : "border-border",
                )}
              >
                <input type="radio" name={groupName} value={period} checked={selected === period} onChange={() => choose(period)} className="sr-only" />
                <span className="flex items-center justify-between gap-2 text-xs font-medium text-muted-foreground">
                  {words.periods[period]}
                  {on ? (
                    <span className="text-foreground">
                      <IconCheck aria-hidden="true" className="size-4" />
                      <span className="sr-only">{words.inTotal}</span>
                    </span>
                  ) : null}
                </span>
                <span className="text-xl leading-tight font-semibold tracking-[-0.03em] tabular-nums">{money(price)}</span>
                <span className="text-xs text-muted-foreground tabular-nums">{fill(words.perDay, { amount: money(Math.round(price / PERIOD_DAYS[period])) })}</span>
                <span className="text-xs text-muted-foreground">{words.covers[period]}</span>
              </label>
            );
          })}
        </div>
      </fieldset>

      <div className="grid gap-6 border-t border-border p-5 @[42rem]:grid-cols-[auto_minmax(0,1fr)] @[42rem]:gap-8">
        <RangeCalendar
          className="@[42rem]:w-[19.5rem]"
          from={fromDay}
          to={toDay}
          onPick={pick}
          booked={booked}
          min={minDay}
          max={lastPickable}
          locale={locale}
          weekStartsOn={weekStartsOn}
          labels={{
            previous: words.previousMonth,
            next: words.nextMonth,
            pickUp: words.pickUp,
            returnDay: words.returnDay,
            booked: words.bookedDay,
            unavailable: words.unavailableDay,
            bookedList: words.bookedList,
            nothingBooked: words.nothingBooked,
            range: words.range,
          }}
        />

        <div className="grid min-w-0 content-start gap-4 rounded-xl border border-border bg-muted/30 p-4">
          <div>
            <p className={caption}>{words.dates}</p>
            {fromDay === null ? (
              <p className="mt-1 text-sm leading-relaxed text-muted-foreground">{words.pickDates}</p>
            ) : toDay === null ? (
              <>
                <p className="mt-1 text-base font-semibold tracking-[-0.01em]">{dayText(fromDay)}</p>
                <p className="mt-1 text-sm leading-relaxed text-muted-foreground">{lastPickable !== null ? fill(words.pickReturnUntil, { date: dayText(lastPickable) }) : words.pickReturn}</p>
              </>
            ) : (
              <>
                <p className="mt-1 text-base font-semibold tracking-[-0.01em]">{fill(words.range, { from: dayText(fromDay), to: dayText(toDay) })}</p>
                <p className="mt-0.5 text-sm text-muted-foreground tabular-nums">{daysText(toDay - fromDay + 1)}</p>
              </>
            )}
            {/* Beside the dates it explains, not above the calendar: when it appears, nothing the person is looking at moves. The region is always there, empty and without height, so a screen reader is already listening when the words arrive. */}
            <p role="status" className="text-xs leading-relaxed text-muted-foreground [&:not(:empty)]:mt-2">
              {notice}
            </p>
          </div>

          {quote ? (
            <ul className="grid gap-2.5 border-t border-border pt-4">
              {quote.lines.map((line) => (
                <li key={line.period} className="flex items-start justify-between gap-3 text-sm">
                  <span className="min-w-0">
                    <span className="block font-medium">{fill(words.rateName, { period: words.periods[line.period] })}</span>
                    <span className="block text-xs text-muted-foreground tabular-nums">
                      {daysText(line.days)}
                      {line.blocks > 1 ? ` · ${numbers.format(line.blocks)} × ${money(rates[line.period] ?? 0)}` : ""}
                    </span>
                  </span>
                  <span className="shrink-0 tabular-nums">{money(line.amount)}</span>
                </li>
              ))}
            </ul>
          ) : null}

          <div role="status" aria-atomic="true" className="grid gap-3 border-t border-border pt-4">
            {saving ? (
              <p className="flex items-start gap-2 text-sm leading-relaxed font-medium">
                <IconCheck aria-hidden="true" className="mt-0.5 size-4 shrink-0" />
                <span className="min-w-0">{saving}</span>
              </p>
            ) : null}
            {fromDay !== null && toDay !== null && !quote ? <p className="text-sm text-muted-foreground">{words.noRate}</p> : null}
            <p className="flex items-baseline justify-between gap-3">
              <span className="text-sm font-medium">{words.total}</span>
              <span className="text-2xl leading-tight font-semibold tracking-[-0.03em] tabular-nums">
                {quote ? (
                  money(quote.total)
                ) : (
                  <>
                    <span aria-hidden="true">–</span>
                    <span className="sr-only">{words.noTotal}</span>
                  </>
                )}
              </span>
            </p>
          </div>

          {deposit !== undefined && deposit > 0 ? (
            <div className="grid gap-1 border-t border-border pt-4">
              <p className="flex items-baseline justify-between gap-3 text-sm">
                <span className="inline-flex items-center gap-2 font-medium">
                  <IconShieldCheck aria-hidden="true" className="size-4 text-muted-foreground" />
                  {words.deposit}
                </span>
                <span className="tabular-nums">{money(deposit)}</span>
              </p>
              <p className="pl-6 text-xs leading-relaxed text-muted-foreground">{words.depositHint}</p>
            </div>
          ) : null}
        </div>
      </div>
    </div>
  );
}

/** The periods a rental can be priced by. */
export type RentalPeriod = "day" | "weekend" | "week" | "month";

/** The rates of one rental, each the price of one whole period in minor units: 9000 is 90.00. Leave out the periods you do not offer. */
export type RentalPrices = Partial<Record<RentalPeriod, number>>;

/** The periods from the shortest to the longest, which is also the order they are shown in. */
export const PERIODS: readonly RentalPeriod[] = ["day", "weekend", "week", "month"];

/** How many days a whole period covers. A weekend is Friday to Sunday, a month is thirty days. */
export const PERIOD_DAYS: Record<RentalPeriod, number> = { day: 1, weekend: 3, week: 7, month: 30 };

const DAY_MS = 86_400_000;

/**
 * A calendar day as a number: whole days since 1970-01-01. Days are counted in UTC, so adding a day or
 * comparing two days never meets a time zone or a clock change.
 */
export function dayNumber(year: number, month: number, date: number): number {
  return Math.round(Date.UTC(year, month, date) / DAY_MS);
}

/** The day a Date falls on in the reader's own calendar, the way the house Calendar reads it. */
export function dayOfDate(date: Date): number {
  return dayNumber(date.getFullYear(), date.getMonth(), date.getDate());
}

/** A Date, or a plain "2026-11-14" that is the same day everywhere, as a day number. Null when it is not a date. */
export function dayOfInput(value: Date | string): number | null {
  if (typeof value === "string") {
    const plain = /^(\d{4})-(\d{2})-(\d{2})/.exec(value);
    if (plain) return dayNumber(Number(plain[1]), Number(plain[2]) - 1, Number(plain[3]));
  }
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? null : dayOfDate(date);
}

/** The day as a Date at midnight in the reader's own time zone: what the house date pickers hand out. */
export function dateOfDay(day: number): Date {
  const utc = new Date(day * DAY_MS);
  return new Date(utc.getUTCFullYear(), utc.getUTCMonth(), utc.getUTCDate());
}

/** The day as a Date at UTC midnight. Write it with an Intl formatter that has timeZone "UTC". */
export function utcDateOf(day: number): Date {
  return new Date(day * DAY_MS);
}

/** 0 is Sunday, 6 is Saturday. */
export function weekdayOf(day: number): number {
  return (((day + 4) % 7) + 7) % 7;
}

/** How many days a rate covers when it starts on `day`. A weekend only starts on a Friday or a Saturday; 0 means it cannot start there. */
export function coverOf(period: RentalPeriod, day: number): number {
  if (period === "weekend") {
    const weekday = weekdayOf(day);
    return weekday === 5 ? 3 : weekday === 6 ? 2 : 0;
  }
  return PERIOD_DAYS[period];
}

/** One line of a quote: a rate, how many times it was used and how many days it paid for. */
export interface RentalLine {
  /** The rate this line is bought at: day, weekend, week or month. */
  period: RentalPeriod;
  /** How many whole periods of this rate were bought. */
  blocks: number;
  /** How many of the rental's days they cover. A week bought for five days covers five. */
  days: number;
  /** In minor units. */
  amount: number;
}

export interface RentalQuote {
  /** Days from pick-up to return, both included. */
  days: number;
  /** The cheapest way to cover them, longest rate first. */
  lines: RentalLine[];
  /** What the lines add up to, in minor units. */
  total: number;
  /** What the same days cost at the day rate alone. Null when there is no day rate. */
  dayRateTotal: number | null;
  /** What the cheapest combination saves against the day rate. 0 when it saves nothing. */
  saving: number;
}

/**
 * The cheapest way to rent from `from` to `to`, both days included. A rate may be bought for fewer days than
 * it covers (a week for five days) when that is the cheaper way; a weekend only starts on a Friday or a
 * Saturday. It is a shortest path over the days, so the answer is the true minimum, and on a tie the plan
 * with the fewest purchases wins. Null when no combination of the rates covers the days.
 */
export function quoteRental(rates: RentalPrices, from: number, to: number): RentalQuote | null {
  const days = to - from + 1;
  if (days < 1) return null;
  const cost = Array.from({ length: days + 1 }, () => Number.POSITIVE_INFINITY);
  const count = Array.from({ length: days + 1 }, () => 0);
  const step: ({ period: RentalPeriod; start: number } | null)[] = Array.from({ length: days + 1 }, () => null);
  cost[0] = 0;
  for (let start = 0; start < days; start++) {
    const here = cost[start] ?? Number.POSITIVE_INFINITY;
    if (here === Number.POSITIVE_INFINITY) continue;
    for (const period of [...PERIODS].reverse()) {
      const price = rates[period];
      const cover = coverOf(period, from + start);
      if (price === undefined || cover === 0) continue;
      const end = Math.min(days, start + cover);
      const next = here + price;
      const blocks = (count[start] ?? 0) + 1;
      if (next < (cost[end] ?? Number.POSITIVE_INFINITY) || (next === cost[end] && blocks < (count[end] ?? 0))) {
        cost[end] = next;
        count[end] = blocks;
        step[end] = { period, start };
      }
    }
  }
  const total = cost[days] ?? Number.POSITIVE_INFINITY;
  if (!Number.isFinite(total)) return null;

  const byPeriod = new Map<RentalPeriod, RentalLine>();
  for (let end = days; end > 0; ) {
    const taken = step[end];
    if (!taken) return null;
    const line = byPeriod.get(taken.period) ?? { period: taken.period, blocks: 0, days: 0, amount: 0 };
    line.blocks += 1;
    line.days += end - taken.start;
    line.amount += rates[taken.period] ?? 0;
    byPeriod.set(taken.period, line);
    end = taken.start;
  }
  const lines = [...byPeriod.values()].sort((a, b) => PERIODS.indexOf(b.period) - PERIODS.indexOf(a.period));
  const dayRateTotal = rates.day === undefined ? null : rates.day * days;
  return { days, lines, total, dayRateTotal, saving: dayRateTotal === null ? 0 : Math.max(0, dayRateTotal - total) };
}

/**
 * The first stretch of days a period fits in, from `start` on, with no blocked day in it. A weekend starts on
 * the first Friday (or the Saturday, when `start` is one); the others start on `start` itself. Looks a year ahead.
 */
export function windowFor(period: RentalPeriod, start: number, blocked: (day: number) => boolean): { from: number; to: number } | null {
  let from = start;
  if (period === "weekend") {
    const weekday = weekdayOf(from);
    if (weekday !== 5 && weekday !== 6) from += (5 - weekday + 7) % 7;
  }
  for (let tries = 0; tries < 370; tries++) {
    const length = coverOf(period, from);
    if (length > 0) {
      let free = true;
      for (let offset = 0; offset < length; offset++) {
        if (blocked(from + offset)) {
          free = false;
          break;
        }
      }
      if (free) return { from, to: from + length - 1 };
    }
    from += period === "weekend" ? 7 : 1;
  }
  return null;
}

/** Groups days that follow each other into runs: [3, 4, 5, 9] becomes [[3, 5], [9, 9]]. */
export function runsOf(days: readonly number[]): [number, number][] {
  const sorted = [...new Set(days)].sort((a, b) => a - b);
  const runs: [number, number][] = [];
  for (const day of sorted) {
    const last = runs[runs.length - 1];
    if (last && last[1] === day - 1) last[1] = day;
    else runs.push([day, day]);
  }
  return runs;
}

"use client";

import { useEffect, useId, useRef, useState, type KeyboardEvent } from "react";

import { IconCalendar, IconChevronLeft, IconChevronRight } from "@rhs-ui/icons";
import { dayNumber, runsOf, utcDateOf, weekdayOf } from "@rhs-ui/commerce/rental-rates/pricing";
import { cn } from "@/lib/utils";

export interface RangeCalendarLabels {
  /** The name of the button that goes to the previous month. */
  previous: string;
  /** The name of the button that goes to the next month. */
  next: string;
  /** Added to the name of the first day of the rental. */
  pickUp: string;
  /** Added to the name of the last day of the rental. */
  returnDay: string;
  /** Added to the name of a day that is booked. */
  booked: string;
  /** Added to the name of a day that cannot be picked for another reason. */
  unavailable: string;
  /** The booked days of the month in words. `{dates}` is the list: "20 to 22 Nov and 4 Dec". */
  bookedList: string;
  /** Said when nothing is booked in the month. `{month}` is its name. */
  nothingBooked: string;
  /** Two ends of a run of days. `{from}` and `{to}`. */
  range: string;
}

export interface RangeCalendarProps {
  /** The first day of the rental as a day number (days since 1970-01-01), or null. */
  from: number | null;
  /** The last day of the rental, or null while it is being chosen. */
  to: number | null;
  /** Called with the day that was picked. */
  onPick: (day: number) => void;
  /** Days that are booked. They are struck through and cannot be picked. */
  booked: ReadonlySet<number>;
  /** The first day that can be picked; earlier days are dimmed. */
  min: number | null;
  /** The last day that can be picked right now. While the return date is chosen it is the day before the next booking. */
  max: number | null;
  /** Locale for the month and day names. */
  locale: string;
  /** 1 is Monday, 0 is Sunday. */
  weekStartsOn?: 0 | 1;
  /** The words the calendar says and the names it gives its buttons. */
  labels: RangeCalendarLabels;
  /** Merged onto the calendar's root. */
  className?: string;
}

const monthIndexOf = (day: number): number => {
  const date = utcDateOf(day);
  return date.getUTCFullYear() * 12 + date.getUTCMonth();
};
const firstOfMonth = (index: number): number => dayNumber(Math.floor(index / 12), index % 12, 1);
/** The month the reader is in now: only asked when nothing else says which month to open on. */
const thisMonth = (): number => {
  const now = new Date();
  return now.getFullYear() * 12 + now.getMonth();
};

/**
 * One month to pick a rental from: first the pick-up day, then the return day, with the days in between
 * drawn as a band. Booked days are struck through and refused, and while the return day is being chosen the
 * days after the next booking are refused too. It is a grid for assistive technology: arrow keys move by day
 * and week, Page Up and Down by month, Home and End to the start and end of the week, Enter picks.
 */
export function RangeCalendar({ from, to, onPick, booked, min, max, locale, weekStartsOn = 1, labels, className }: RangeCalendarProps) {
  const id = useId();
  const grid = useRef<HTMLDivElement>(null);
  const [month, setMonth] = useState(() => (from ?? min) !== null ? monthIndexOf((from ?? min) as number) : thisMonth());
  const [focus, setFocus] = useState<number | null>(null);
  const [hover, setHover] = useState<number | null>(null);

  // A rental that jumps to another month (a rate chosen, a new pick-up day) brings the calendar along.
  useEffect(() => {
    if (from !== null) setMonth(monthIndexOf(from));
  }, [from]);

  const first = firstOfMonth(month);
  const offset = (weekdayOf(first) - weekStartsOn + 7) % 7;
  const length = firstOfMonth(month + 1) - first;
  const cells = Array.from({ length: Math.ceil((offset + length) / 7) * 7 }, (_, index) => first - offset + index);
  const weeks = Array.from({ length: cells.length / 7 }, (_, index) => cells.slice(index * 7, index * 7 + 7));
  const weekdays = Array.from({ length: 7 }, (_, index) => {
    const day = first - offset + index;
    return {
      short: new Intl.DateTimeFormat(locale, { weekday: "narrow", timeZone: "UTC" }).format(utcDateOf(day)),
      long: new Intl.DateTimeFormat(locale, { weekday: "long", timeZone: "UTC" }).format(utcDateOf(day)),
    };
  });
  const title = new Intl.DateTimeFormat(locale, { month: "long", year: "numeric", timeZone: "UTC" }).format(utcDateOf(first));
  const full = new Intl.DateTimeFormat(locale, { weekday: "long", day: "numeric", month: "long", year: "numeric", timeZone: "UTC" });

  const refusedReason = (day: number): "booked" | "unavailable" | null => {
    if (booked.has(day)) return "booked";
    if ((min !== null && day < min) || (max !== null && to === null && from !== null && day > from && day > max)) return "unavailable";
    return null;
  };
  // While the return day is being chosen, the band follows the pointer or the focus.
  const end = to ?? (from !== null && hover !== null && hover >= from && refusedReason(hover) === null ? hover : null);

  const goTo = (day: number) => {
    setFocus(day);
    const index = monthIndexOf(day);
    if (index !== month) setMonth(index);
    requestAnimationFrame(() => grid.current?.querySelector<HTMLButtonElement>(`[data-day="${day}"]`)?.focus());
  };
  const onKey = (event: KeyboardEvent<HTMLButtonElement>, day: number) => {
    const weekday = (weekdayOf(day) - weekStartsOn + 7) % 7;
    const sameDayNextMonth = (step: number): number => {
      const date = utcDateOf(day);
      const target = date.getUTCFullYear() * 12 + date.getUTCMonth() + step;
      const last = firstOfMonth(target + 1) - 1;
      return Math.min(firstOfMonth(target) + date.getUTCDate() - 1, last);
    };
    const moves: Record<string, number> = { ArrowLeft: day - 1, ArrowRight: day + 1, ArrowUp: day - 7, ArrowDown: day + 7, Home: day - weekday, End: day + 6 - weekday, PageUp: sameDayNextMonth(-1), PageDown: sameDayNextMonth(1) };
    const next = moves[event.key];
    if (next === undefined) return;
    event.preventDefault();
    goTo(next);
  };

  // The bookings of the month on show, in words: what is struck through in the grid, said aloud as well.
  const monthEnd = first + length - 1;
  const dayOnly = new Intl.DateTimeFormat(locale, { day: "numeric", timeZone: "UTC" });
  const dayAndMonth = new Intl.DateTimeFormat(locale, { day: "numeric", month: "short", timeZone: "UTC" });
  const runs = runsOf([...booked].filter((day) => day >= first && day <= monthEnd)).map(([start, last]) =>
    start === last ? dayAndMonth.format(utcDateOf(start)) : labels.range.replace("{from}", dayOnly.format(utcDateOf(start))).replace("{to}", dayAndMonth.format(utcDateOf(last))),
  );
  const monthName = new Intl.DateTimeFormat(locale, { month: "long", timeZone: "UTC" }).format(utcDateOf(first));
  const bookedNote = runs.length ? labels.bookedList.replace("{dates}", new Intl.ListFormat(locale, { style: "long", type: "conjunction" }).format(runs)) : labels.nothingBooked.replace("{month}", monthName);

  const rovingDay = focus !== null && monthIndexOf(focus) === month ? focus : from !== null && monthIndexOf(from) === month ? from : (cells.find((day) => monthIndexOf(day) === month && refusedReason(day) === null) ?? first);
  const step = "grid size-8 place-items-center rounded-md text-muted-foreground outline-none hover:bg-muted hover:text-foreground focus-visible:ring-[3px] focus-visible:ring-ring/40 disabled:pointer-events-none disabled:opacity-40";

  return (
    <div data-slot="range-calendar" className={cn("w-full min-w-0 select-none", className)}>
      <div className="mb-2 flex items-center justify-between gap-2">
        <button type="button" aria-label={labels.previous} disabled={min !== null && month <= monthIndexOf(min)} onClick={() => setMonth(month - 1)} className={step}>
          <IconChevronLeft size={16} />
        </button>
        <p id={`${id}-title`} aria-live="polite" className="text-sm font-medium capitalize">
          {title}
        </p>
        <button type="button" aria-label={labels.next} onClick={() => setMonth(month + 1)} className={step}>
          <IconChevronRight size={16} />
        </button>
      </div>
      <div ref={grid} role="grid" aria-labelledby={`${id}-title`}>
        <div role="row" className="grid grid-cols-7">
          {weekdays.map((day) => (
            <span key={day.long} role="columnheader" aria-label={day.long} className="grid h-8 place-items-center text-[0.6875rem] font-medium text-muted-foreground uppercase">
              {day.short}
            </span>
          ))}
        </div>
        {weeks.map((week) => (
          <div key={week[0]} role="row" className="grid grid-cols-7">
            {week.map((day) => {
              const inMonth = monthIndexOf(day) === month;
              const reason = refusedReason(day);
              const isFrom = from === day;
              const isTo = to === day;
              const inBand = from !== null && end !== null && day >= from && day <= end && from !== end;
              const bandStart = inBand && day === from;
              const bandEnd = inBand && day === end;
              const picked = isFrom || isTo;
              const name = [full.format(utcDateOf(day)), isFrom ? labels.pickUp : null, isTo ? labels.returnDay : null, reason === "booked" ? labels.booked : reason === "unavailable" ? labels.unavailable : null].filter(Boolean).join(", ");
              return (
                <span key={day} role="gridcell" aria-selected={picked || (to !== null && inBand) || undefined} className="relative grid h-9 place-items-center">
                  {inBand && inMonth ? <span aria-hidden="true" className={cn("absolute inset-y-0.5 bg-muted", bandStart ? "right-0 left-1/2" : bandEnd ? "right-1/2 left-0" : "inset-x-0")} /> : null}
                  {inMonth ? (
                    <button
                      type="button"
                      data-day={day}
                      tabIndex={day === rovingDay ? 0 : -1}
                      aria-disabled={reason !== null || undefined}
                      aria-label={name}
                      onClick={() => {
                        setFocus(day);
                        if (reason === null) onPick(day);
                      }}
                      onKeyDown={(event) => (event.key === "Enter" || event.key === " " ? (event.preventDefault(), reason === null && onPick(day)) : onKey(event, day))}
                      onPointerEnter={() => setHover(day)}
                      onPointerLeave={() => setHover(null)}
                      onFocus={() => setHover(day)}
                      onBlur={() => setHover(null)}
                      className={cn(
                        "relative grid size-9 place-items-center rounded-full text-sm tabular-nums outline-none transition-colors duration-100 focus-visible:ring-[3px] focus-visible:ring-ring/40 motion-reduce:transition-none",
                        picked ? "bg-foreground font-medium text-background" : reason === null ? "text-foreground hover:bg-muted" : "cursor-not-allowed",
                        !picked && reason === "booked" && "text-muted-foreground line-through decoration-muted-foreground/70",
                        !picked && reason === "unavailable" && "text-muted-foreground/45",
                        !picked && inBand && reason === null && "hover:bg-background/60",
                      )}
                    >
                      {utcDateOf(day).getUTCDate()}
                    </button>
                  ) : null}
                </span>
              );
            })}
          </div>
        ))}
      </div>
      <p aria-live="polite" className="mt-3 flex items-start gap-2 text-xs leading-relaxed text-muted-foreground">
        <IconCalendar aria-hidden="true" className="mt-px size-3.5 shrink-0" />
        <span className="min-w-0">{bookedNote}</span>
      </p>
    </div>
  );
}
